//! Unicode 13.0 character names (the UCD perl 5.34 ships) for `\N{NAME}` and
//! `charnames`: every `UnicodeData.txt` name and `NameAliases.txt` alias, and
//! the algorithmic Hangul syllable, CJK unified and Tangut ideograph names.
//!
//! Lookups match loosely (UAX44-LM2): case, whitespace, underscores and
//! medial hyphens are ignored, except the hyphen of U+1180 HANGUL JUNGSEONG
//! O-E. `charnames.zst` is regenerated by `tools/gen-charnames.py`.

use std::{collections::HashMap, sync::LazyLock};

const HANGUL_FIRST: u32 = 0xAC00;
const HANGUL_LAST: u32 = 0xD7A3;
const HANGUL_PREFIX: &str = "HANGUL SYLLABLE ";
const LEADS: [&str; 19] = ["G", "GG", "N", "D", "DD", "R", "M", "B", "BB", "S", "SS", "", "J", "JJ", "C", "K", "T", "P", "H"];
const VOWELS: [&str; 21] = [
	"A", "AE", "YA", "YAE", "EO", "E", "YEO", "YE", "O", "WA", "WAE", "OE", "YO", "U", "WEO", "WE", "WI", "YU", "EU", "YI", "I",
];
const TAILS: [&str; 28] = [
	"", "G", "GG", "GS", "N", "NJ", "NH", "D", "L", "LG", "LM", "LB", "LS", "LT", "LP", "LH", "M", "B", "BS", "S", "SS", "NG", "J",
	"C", "K", "T", "P", "H",
];

struct Names {
	/// Loose keys of every name and alias (names win over aliases).
	by_name: HashMap<Vec<u8>, u32>,
	/// `UnicodeData.txt` names, ascending by code point.
	by_code: Vec<(u32, &'static str)>,
	/// Ranges named by their prefix and the code point in hex, with the
	/// prefix's loose key.
	ranges:  Vec<(u32, u32, &'static str, Vec<u8>)>,
}

static NAMES: LazyLock<Names> = LazyLock::new(|| {
	let text = zstd::decode_all(&include_bytes!("charnames.zst")[..]).expect("charnames.zst is valid zstd");
	let text = String::leak(String::from_utf8(text).expect("charnames.zst holds UTF-8"));
	let hex = |code: &str| u32::from_str_radix(code, 16).expect("charnames.zst holds hex code points");
	let mut names = Names { by_name: HashMap::new(), by_code: Vec::new(), ranges: Vec::new() };
	let mut aliases = Vec::new();
	for record in text.lines() {
		let (kind, record) = record.split_at(1);
		let mut fields = record.split(';');
		let (Some(code), Some(name)) = (fields.next(), fields.next()) else { continue };
		match kind {
			"N" => names.by_code.push((hex(code), name)),
			"A" => aliases.push((hex(code), name)),
			"R" => {
				let Some(prefix) = fields.next() else { continue };
				let key = loose(prefix.trim_end_matches('-')).unwrap_or_default();
				names.ranges.push((hex(code), hex(name), prefix, key));
			},
			_ => {},
		}
	}
	for &(cp, name) in &names.by_code {
		// U+1180 keeps its hyphen apart from U+116C HANGUL JUNGSEONG OE.
		let key = if cp == 0x1180 { name.bytes().filter(|&b| b != b' ').collect() } else { loose(name).unwrap_or_default() };
		names.by_name.insert(key, cp);
	}
	for cp in HANGUL_FIRST..=HANGUL_LAST {
		let key = loose(&hangul_name(cp)).unwrap_or_default();
		names.by_name.insert(key, cp);
	}
	for (cp, alias) in aliases {
		names.by_name.entry(loose(alias).unwrap_or_default()).or_insert(cp);
	}
	names
});

/// The code point named `name` (a name or an alias), matched loosely.
pub(super) fn character(name: &str) -> Option<u32> {
	let key = loose(name)?;
	let names = &*NAMES;
	if let Some(&cp) = names.by_name.get(&key) {
		// "HANGUL JUNGSEONG O-E" loosens to U+116C's key; its hyphen before the
		// final letter tells U+1180 apart.
		let spelled = name.trim_end_matches(|c: char| c.is_ascii_whitespace() || c == '_');
		if cp == 0x116C && spelled.bytes().nth_back(1) == Some(b'-') {
			return Some(0x1180);
		}
		return Some(cp);
	}
	names.ranges.iter().find_map(|(first, last, _, prefix)| {
		let digits = key.strip_prefix(prefix.as_slice())?;
		if digits.is_empty() || digits.len() > 6 {
			return None;
		}
		let cp = u32::from_str_radix(std::str::from_utf8(digits).ok()?, 16).ok()?;
		(first..=last).contains(&&cp).then_some(cp)
	})
}

/// The `UnicodeData.txt` (or algorithmic) name of `cp`; `None` for an
/// unnamed code point (controls among them).
pub(super) fn name(cp: u32) -> Option<String> {
	if (HANGUL_FIRST..=HANGUL_LAST).contains(&cp) {
		return Some(hangul_name(cp));
	}
	let names = &*NAMES;
	if let Some((.., prefix, _)) = names.ranges.iter().find(|(first, last, ..)| (first..=last).contains(&&cp)) {
		return Some(format!("{prefix}{cp:04X}"));
	}
	let at = names.by_code.binary_search_by_key(&cp, |&(code, _)| code).ok()?;
	Some(names.by_code[at].1.to_owned())
}

/// `HANGUL SYLLABLE ` and the jamo short names of Hangul syllable `cp`.
fn hangul_name(cp: u32) -> String {
	let index = (cp - HANGUL_FIRST) as usize;
	let (lead, rest) = (index / (21 * 28), index % (21 * 28));
	[HANGUL_PREFIX, LEADS[lead], VOWELS[rest / 28], TAILS[rest % 28]].concat()
}

/// `name`'s UAX44-LM2 loose key: ASCII uppercase without whitespace,
/// underscores and medial hyphens; `None` when it holds anything a Unicode
/// name cannot.
fn loose(name: &str) -> Option<Vec<u8>> {
	let bytes = name.as_bytes();
	let mut key = Vec::with_capacity(bytes.len());
	for (at, &byte) in bytes.iter().enumerate() {
		let byte = byte.to_ascii_uppercase();
		if byte.is_ascii_whitespace() || byte == b'_' {
			continue;
		}
		let medial = byte == b'-'
			&& at.checked_sub(1).is_some_and(|before| bytes[before].is_ascii_alphanumeric())
			&& bytes.get(at + 1).is_some_and(u8::is_ascii_alphanumeric);
		if medial {
			continue;
		}
		if !byte.is_ascii_alphanumeric() && byte != b'-' {
			return None;
		}
		key.push(byte);
	}
	Some(key)
}

#[cfg(test)]
mod tests {
	use super::{character, name};

	#[test]
	fn names_aliases_and_algorithmic_names_resolve_both_ways() {
		for (spelled, cp) in [
			("LATIN SMALL LETTER A", 0x61),
			("latin_small-letter a", 0x61),
			("SNOWMAN", 0x2603),
			("LINE FEED", 0x0A),
			("ZWJ", 0x200D),
			("HANGUL SYLLABLE GA", 0xAC00),
			("HANGUL SYLLABLE BWELG", 0xBDC1),
			("HANGUL JUNGSEONG OE", 0x116C),
			("HANGUL JUNGSEONG O-E", 0x1180),
			("CJK UNIFIED IDEOGRAPH-4E00", 0x4E00),
			("TANGUT IDEOGRAPH-17000", 0x17000),
		] {
			assert_eq!(character(spelled), Some(cp), "{spelled}");
		}
		assert_eq!(character("CJK UNIFIED IDEOGRAPH-9FFD"), None, "past Unicode 13.0's range");
		assert_eq!(character("SNOWMAN!"), None);
		assert_eq!(name(0xBDC1).as_deref(), Some("HANGUL SYLLABLE BWELG"));
		assert_eq!(name(0x2A6DD).as_deref(), Some("CJK UNIFIED IDEOGRAPH-2A6DD"));
		assert_eq!(name(0x1180).as_deref(), Some("HANGUL JUNGSEONG O-E"));
		assert_eq!(name(0x0A), None, "controls have no UnicodeData name");
	}
}
